static inline uint16_t vring_avail_idx(VirtQueue *vq) /* <=== vring_avail_idx */ 
{
    hwaddr pa;
    pa = vq->vring.avail + offsetof(VRingAvail, idx);
    return lduw_phys(&address_space_memory, pa);
}

int virtio_set_features(VirtIODevice *vdev, uint32_t val) /* <=== virtio_set_features */ 
{
    BusState *qbus = qdev_get_parent_bus(DEVICE(vdev));
    VirtioBusClass *vbusk = VIRTIO_BUS_GET_CLASS(qbus);
    VirtioDeviceClass *k = VIRTIO_DEVICE_GET_CLASS(vdev);
    uint32_t supported_features = vbusk->get_features(qbus->parent);
    bool bad = (val & ~supported_features) != 0;

    val &= supported_features;
    if (k->set_features) {
        k->set_features(vdev, val);
    }
    vdev->guest_features = val;
    return bad ? -1 : 0;
}

unsigned int qemu_get_be32(QEMUFile *f) /* <=== qemu_get_be32 */ 
{
    unsigned int v;
    v = qemu_get_byte(f) << 24;
    v |= qemu_get_byte(f) << 16;
    v |= qemu_get_byte(f) << 8;
    v |= qemu_get_byte(f);
    return v;
}

void error_printf(const char *fmt, ...) /* <=== error_printf */ 
{
    va_list ap;

    va_start(ap, fmt);
    error_vprintf(fmt, ap);
    va_end(ap);
}

void qemu_file_skip(QEMUFile *f, int size) /* <=== qemu_file_skip */ 
{
    if (f->buf_index + size <= f->buf_size) {
        f->buf_index += size;
    }
}

uint64_t qemu_get_be64(QEMUFile *f) /* <=== qemu_get_be64 */ 
{
    uint64_t v;
    v = (uint64_t)qemu_get_be32(f) << 32;
    v |= qemu_get_be32(f);
    return v;
}

static void error_print_loc(void) /* <=== error_print_loc */ 
{
    const char *sep = "";
    int i;
    const char *const *argp;

    if (!cur_mon && progname) {
        fprintf(stderr, "%s:", progname);
        sep = " ";
    }
    switch (cur_loc->kind) {
    case LOC_CMDLINE:
        argp = cur_loc->ptr;
        for (i = 0; i < cur_loc->num; i++) {
            error_printf("%s%s", sep, argp[i]);
            sep = " ";
        }
        error_printf(": ");
        break;
    case LOC_FILE:
        error_printf("%s:", (const char *)cur_loc->ptr);
        if (cur_loc->num) {
            error_printf("%d:", cur_loc->num);
        }
        error_printf(" ");
        break;
    default:
        error_printf("%s", sep);
    }
}

static inline hwaddr vring_align(hwaddr addr, /* <=== vring_align */ 
                                             unsigned long align)
{
    return (addr + align - 1) & ~(align - 1);
}

void error_report(const char *fmt, ...) /* <=== error_report */ 
{
    va_list ap;
    GTimeVal tv;
    gchar *timestr;

    if (enable_timestamp_msg) {
        g_get_current_time(&tv);
        timestr = g_time_val_to_iso8601(&tv);
        error_printf("%s ", timestr);
        g_free(timestr);
    }

    error_print_loc();
    va_start(ap, fmt);
    error_vprintf(fmt, ap);
    va_end(ap);
    error_printf("\n");
}

static void virtio_notify_vector(VirtIODevice *vdev, uint16_t vector) /* <=== virtio_notify_vector */ 
{
    BusState *qbus = qdev_get_parent_bus(DEVICE(vdev));
    VirtioBusClass *k = VIRTIO_BUS_GET_CLASS(qbus);

    if (k->notify) {
        k->notify(qbus->parent, vector);
    }
}

int qemu_get_byte(QEMUFile *f) /* <=== qemu_get_byte */ 
{
    int result;

    result = qemu_peek_byte(f, 0);
    qemu_file_skip(f, 1);
    return result;
}

void error_vprintf(const char *fmt, va_list ap) /* <=== error_vprintf */ 
{
    if (cur_mon && !monitor_cur_is_qmp()) {
        monitor_vprintf(cur_mon, fmt, ap);
    } else {
        vfprintf(stderr, fmt, ap);
    }
}

unsigned int qemu_get_be16(QEMUFile *f) /* <=== qemu_get_be16 */ 
{
    unsigned int v;
    v = qemu_get_byte(f) << 8;
    v |= qemu_get_byte(f);
    return v;
}

int qemu_peek_byte(QEMUFile *f, int offset) /* <=== qemu_peek_byte */ 
{
    int index = f->buf_index + offset;

    assert(!qemu_file_is_writable(f));

    if (index >= f->buf_size) {
        qemu_fill_buffer(f);
        index = f->buf_index + offset;
        if (index >= f->buf_size) {
            return 0;
        }
    }
    return f->buf[index];
}

static inline void qemu_get_be16s(QEMUFile *f, uint16_t *pv) /* <=== qemu_get_be16s */ 
{
    *pv = qemu_get_be16(f);
}

static void virtqueue_init(VirtQueue *vq) /* <=== virtqueue_init */ 
{
    hwaddr pa = vq->pa;

    vq->vring.desc = pa;
    vq->vring.avail = pa + vq->vring.num * sizeof(VRingDesc);
    vq->vring.used = vring_align(vq->vring.avail +
                                 offsetof(VRingAvail, ring[vq->vring.num]),
                                 vq->vring.align);
}

